// AI: below section was generated by an AI
// Bake confirmed captions into the source PNGs and compact WebPs without altering car pixels.
const fs = require("node:fs");
const path = require("node:path");
const http = require("node:http");
const { spawnSync } = require("node:child_process");
const { chromium } = require(process.env.GLASSLIGHT_PLAYWRIGHT || "playwright");

const captions = {
	efr7: { text: "JulE 2014", bottom: 0.798 },
	efr8: { text: "LucE 2015", bottom: 0.767 },
	efr12: { text: "LilliE 2019", bottom: 0.78 },
	efr14: { text: "HerminE 2022", bottom: 0.788 },
	efr17: { text: "ZOE 2025", bottom: 0.791 },
};
const web = path.join(__dirname, "web");
const output = path.resolve(__dirname, "../../build_output/model-captions");
const original = path.join(output, "originals");
const allowedPaths = new Set(Object.keys(captions).map((id) => "/model-" + id + ".png"));

// Reuse the existing indexed-PNG encoder and lossless WebP settings.
function prepare(source, destination, flag) {
	const result = spawnSync(
		process.env.GLASSLIGHT_PYTHON || "python",
		[path.join(__dirname, "prepare_models.py"), source, destination, flag],
		{ stdio: "inherit" },
	);
	if (result.error) throw result.error;
	if (result.status !== 0) throw new Error("Model encoding failed: " + destination);
}

// Same-origin input permits alpha export while preserving the transparent model masks.
async function main() {
	fs.mkdirSync(original, { recursive: true });
	const server = http.createServer((request, response) => {
		if (allowedPaths.has(request.url)) {
			response.setHeader("Content-Type", "image/png");
			fs.createReadStream(path.join(web, request.url.slice(1))).pipe(response);
		} else if (request.url === "/") {
			response.setHeader("Content-Type", "text/html");
			response.end("<!doctype html><title>Offline caption baker</title>");
		} else {
			response.writeHead(404).end();
		}
	});
	await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
	let browser;
	try {
		browser = await chromium.launch({ executablePath: process.env.GLASSLIGHT_BROWSER, headless: true });
		const page = await browser.newPage();
		await page.goto("http://127.0.0.1:" + server.address().port);
		for (const [id, caption] of Object.entries(captions)) {
			for (const extension of ["png", "webp"]) {
				const filename = "model-" + id + "." + extension;
				if (!fs.existsSync(path.join(original, filename)))
					fs.copyFileSync(path.join(web, filename), path.join(original, filename));
			}
			const encoded = await page.evaluate(
				async ({ id, text, bottom }) => {
					const image = new Image();
					image.src = "/model-" + id + ".png";
					await image.decode();
					if (image.naturalWidth !== 1600 || image.naturalHeight !== 1000)
						throw new Error("Expected a 1600 x 1000 source mask");
					const canvas = document.createElement("canvas");
					canvas.width = image.naturalWidth;
					canvas.height = image.naturalHeight;
					const ctx = canvas.getContext("2d");
					ctx.drawImage(image, 0, 0);
					// Clear only the reserved blank area so rerunning never stacks captions.
					const carBottom = Math.ceil(canvas.height * bottom);
					ctx.clearRect(0, carBottom, canvas.width, canvas.height - carBottom);
					const lettering = document.createElement("canvas");
					const textContext = lettering.getContext("2d");
					// Match DaisiE's native text height and 30-pixel separation beneath the car.
					const font = "84px Arial, sans-serif";
					const padding = 2;
					textContext.font = font;
					const metrics = textContext.measureText(text);
					lettering.width = Math.ceil(metrics.width) + padding * 2;
					lettering.height =
						Math.ceil(metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent) + padding * 2;
					textContext.font = font;
					textContext.fillStyle = "white";
					textContext.fillText(text, padding, padding + metrics.actualBoundingBoxAscent);
					const pixels = textContext.getImageData(0, 0, lettering.width, lettering.height);
					// Stable grain reproduces the existing speckled lettering.
					for (let i = 3; i < pixels.data.length; i += 4) {
						if (!pixels.data[i]) continue;
						const hash = Math.imul(i, 0x45d9f3b);
						const grain = ((hash ^ (hash >>> 16)) >>> 0) / 0xffffffff;
						pixels.data[i] = grain < 0.08 ? 0 : Math.round(pixels.data[i] * (0.12 + grain * 0.3));
					}
					textContext.putImageData(pixels, 0, 0);
					ctx.drawImage(lettering, Math.round((canvas.width - lettering.width) / 2), carBottom + 30);
					const rgba = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
					const alpha = new Uint8Array(canvas.width * canvas.height);
					for (let i = 0; i < alpha.length; i++) alpha[i] = Math.round(rgba[i * 4 + 3] / 17);
					let binary = "";
					for (let i = 0; i < alpha.length; i += 8192) binary += String.fromCharCode(...alpha.subarray(i, i + 8192));
					return btoa(binary);
				},
				{ id, ...caption },
			);
			const alpha = path.join(output, id + ".alpha");
			const png = path.join(web, "model-" + id + ".png");
			fs.writeFileSync(alpha, Buffer.from(encoded, "base64"));
			prepare(alpha, png, "--alpha");
			prepare(png, path.join(web, "model-" + id + ".webp"), "--compact");
			console.log(id + ": baked " + caption.text);
		}
	} finally {
		if (browser) await browser.close();
		await new Promise((resolve) => server.close(resolve));
	}
}
main().catch((error) => {
	console.error(error);
	process.exitCode = 1;
});
// AI: end
